static uint32_t word(const void*p,size_t at){uint32_t v;memcpy(&v,(const unsigned char*)p+at,4);return v;}
static int32_t bits(uint32_t v){int32_t r;memcpy(&r,&v,4);return r;}
static int32_t get(const void*p,size_t at){return bits(word(p,at));}
static int32_t add(int32_t a,int32_t b){return bits((uint32_t)a+(uint32_t)b);}
static int32_t sub(int32_t a,int32_t b){return bits((uint32_t)a-(uint32_t)b);}
static int32_t mul(int32_t a,int32_t b){return bits((uint32_t)a*(uint32_t)b);}
static int32_t shl(int32_t a,unsigned n){return bits((uint32_t)a<<n);}
static int16_t short_bits(int32_t a){uint16_t v=(uint16_t)a;int16_t r;memcpy(&r,&v,2);return r;}
static int format(unsigned shift,unsigned height,unsigned affine){return shift<=10&&height>=2&&height<=INT32_MAX&&!(height&1)&&affine<=1;}
static int projected(const void*table,int depth,const int32_t*a,unsigned shift,unsigned height,unsigned affine,double out[2]){if(!table||!format(shift,height,affine)||depth<1||depth>=32768)return 0;uint32_t r=word(table,(size_t)depth*4);if(!r)return 0;for(unsigned k=0;k<2;k++){int32_t scaled=k?mul(a[k],bits(height)):shl(a[k],shift),v=affine?shl(scaled,1):bits((uint32_t)(((int64_t)(scaled>>7)*r)>>8));double denominator=k?height*.5:(1u<<shift)*.5;out[k]=(double)v/(affine?65536.0:(double)r)/denominator;}return 1;}
int nf_pc_road_vertex(const void*table,double depth,const int32_t a[2],unsigned shift,unsigned height,unsigned affine,double out[2]){if(!a||!out||!isfinite(depth)||depth<1||depth>32767)return 0;int lo=(int)floor(depth);double t=depth-lo,v[2],b[2];if(!projected(table,lo,a,shift,height,affine,v))return 0;if(t!=0){if(!projected(table,lo+1,a,shift,height,affine,b))return 0;for(unsigned k=0;k<2;k++)v[k]+= (b[k]-v[k])*t;}memcpy(out,v,sizeof(v));return 1;}
static int near_integer(const void*table,int z0,int z1,const int32_t*a,unsigned shift,unsigned height,unsigned affine,int near,double out[2]){int start=z0<near||(z0==near&&z1>=near),behind=start?z0:z1,front=start?z1:z0,delta=front-behind;if(behind>near||front<near||delta<0||delta>=32768||near<1||near>=32768||!word(table,(size_t)near*4))return 0;uint32_t factor=(uint32_t)((uint64_t)(near-behind)*word(table,(size_t)delta*4));int32_t clipped[2];for(unsigned k=0;k<2;k++){int32_t difference=sub(a[k+2],a[k]);int32_t adjustment=bits((uint32_t)(((int64_t)difference*factor)>>24));clipped[k]=start?add(a[k],adjustment):sub(a[k+2],adjustment);}return projected(table,near,clipped,shift,height,affine,out);}
int nf_pc_road_near(const void*table,double z0,double z1,const int32_t a[4],unsigned shift,unsigned height,unsigned affine,int near,double out[2]){if(!table||!a||!out||!isfinite(z0)||!isfinite(z1)||z0< -32768||z0>32767||z1< -32768||z1>32767||!((z0<near&&z1>=near)||(z1<near&&z0>=near))||!format(shift,height,affine))return 0;int x=(int)floor(z0),y=(int)floor(z1);double tx=z0-x,ty=z1-y,v[2]={0};for(unsigned i=0;i<2;i++)for(unsigned j=0;j<2;j++){double w=(i?tx:1-tx)*(j?ty:1-ty),corner[2];if(w==0)continue;if(!near_integer(table,x+i,y+j,a,shift,height,affine,near,corner))return 0;for(unsigned k=0;k<2;k++)v[k]+=w*corner[k];}memcpy(out,v,sizeof(v));return 1;}
static double axis(const void*camera,int32_t x,int32_t z,unsigned k){int32_t a=add(x,get(camera,8+9*4)),b=add(z,get(camera,8+11*4)),v=add(mul(a,get(camera,8+k*4)),mul(b,get(camera,8+(6+k)*4)));return short_bits(v>>14);}
int nf_pc_road_camera(const void*camera,size_t n,const double p[3],double out[3]){if(!camera||n!=56||word(camera,0)!=1||(word(camera,4)&3)||!p||!out)return 0;for(unsigned k=0;k<3;k++)if(!isfinite(p[k])||p[k]<INT32_MIN||p[k]>INT32_MAX-1.0)return 0;int32_t x=(int32_t)floor(p[0]),z=(int32_t)floor(p[2]);double fx=p[0]-x,fz=p[2]-z,r[3]={0,p[1]+get(camera,8+10*4),0};for(unsigned i=0;i<2;i++)for(unsigned j=0;j<2;j++){double w=(i?fx:1-fx)*(j?fz:1-fz);if(w==0)continue;r[0]+=w*axis(camera,x+(int)i,z+(int)j,0);r[2]+=w*axis(camera,x+(int)i,z+(int)j,2);}memcpy(out,r,sizeof(r));return 1;}
int nf_pc_road_clip(const void*table,const double*camera,unsigned count,const void*raw,size_t bytes,double out[64][5],unsigned*out_count){if(!table||!camera||count<3||count>32||!raw||bytes!=288||!out||!out_count||word(raw,0)!=count)return 0;unsigned shift=word(raw,4),height=word(raw,8),affine=word(raw,12);if(!format(shift,height,affine))return 0;double offset_u=get(raw,24)/(256.0*(1u<<shift)),offset_v=get(raw,28)/(256.0*height),result[64][5];unsigned n=0;
 for(unsigned i=0;i<count;i++){unsigned previous=(i+count-1)%count;const double*a=camera+previous*3,*b=camera+i*3;for(unsigned k=0;k<3;k++)if(!isfinite(a[k])||!isfinite(b[k]))return 0;int ai=a[2]>=64,bi=b[2]>=64;if(ai!=bi){int32_t attrs[4]={get(raw,32+previous*8),get(raw,36+previous*8),get(raw,32+i*8),get(raw,36+i*8)};double uv[2];if(!nf_pc_road_near(table,a[2],b[2],attrs,shift,height,affine,64,uv))return 0;double t=(64-a[2])/(b[2]-a[2]);double v[5]={a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,64,uv[0]+offset_u,uv[1]+offset_v};memcpy(result[n++],v,sizeof(v));}if(bi){int32_t attrs[2]={get(raw,32+i*8),get(raw,36+i*8)};double uv[2];if(!nf_pc_road_vertex(table,b[2],attrs,shift,height,affine,uv))return 0;double v[5]={b[0],b[1],b[2],uv[0]+offset_u,uv[1]+offset_v};memcpy(result[n++],v,sizeof(v));}}
 memcpy(out,result,n*5*sizeof(double));*out_count=n;return 1;}
static double coordinate(const void*table,int32_t value,int z,int32_t scale,int32_t center,int x){int32_t factor=mul(get(table,(size_t)z*4),scale)>>7;int32_t result=add(center,mul(value>>1,factor)>>16);return x?short_bits(result):result;}
static int integer_attributes(const void*table,const double*p,const int32_t*attrs,unsigned shift,unsigned height,const int32_t*projection,double out[5]){if(!table||!p||!attrs||!projection||shift>10||height<2||height>65535||projection[2]<0)return 0;for(unsigned k=0;k<3;k++)if(!isfinite(p[k])||p[k]<(k==2?1:-32768)||p[k]>(k==2?32767:32767))return 0;int32_t base[3];double frac[3],r[5]={0};for(unsigned k=0;k<3;k++){base[k]=(int32_t)floor(p[k]);frac[k]=p[k]-base[k];}
 for(unsigned k=0;k<2;k++)for(unsigned i=0;i<2;i++)for(unsigned j=0;j<2;j++){double w=(i?frac[k]:1-frac[k])*(j?frac[2]:1-frac[2]);if(w==0)continue;r[k]+=w*coordinate(table,base[k]+(int)i,base[2]+(int)j,projection[2],projection[k],k==0);}
 for(unsigned j=0;j<2;j++){double w=j?frac[2]:1-frac[2];if(w==0)continue;int32_t reciprocal=get(table,(size_t)(base[2]+(int)j)*4);r[2]+=w*(uint32_t)reciprocal;for(unsigned k=0;k<2;k++){int32_t scaled=k?mul(attrs[k],bits(height)):shl(attrs[k],shift);int64_t product=(int64_t)(scaled>>7)*reciprocal;r[3+k]+=w*bits((uint32_t)((uint64_t)product>>8));}}
 for(unsigned k=0;k<5;k++)if(!isfinite(r[k]))return 0;
memcpy(out,r,sizeof(r));return 1;}
int nf_pc_road_project_point(const void*table,const double point[3],const double attrs[2],unsigned shift,unsigned height,const int32_t projection[3],double out[5]){if(!attrs||!out)return 0;int32_t base[2];double frac[2],r[5]={0};for(unsigned k=0;k<2;k++){if(!isfinite(attrs[k])||attrs[k]<INT32_MIN||attrs[k]>INT32_MAX-1.0)return 0;base[k]=(int32_t)floor(attrs[k]);frac[k]=attrs[k]-base[k];}for(unsigned i=0;i<2;i++)for(unsigned j=0;j<2;j++){double w=(i?frac[0]:1-frac[0])*(j?frac[1]:1-frac[1]),v[5];if(w==0)continue;int32_t a[2]={base[0]+(int)i,base[1]+(int)j};if(!integer_attributes(table,point,a,shift,height,projection,v))return 0;for(unsigned k=0;k<5;k++)r[k]+=w*v[k];}memcpy(out,r,sizeof(r));return 1;}
static int near_core(const void*table,const double*a,const double*b,double near,double out[5]){if(!table||!a||!b||!isfinite(near)||near<1||near>32766)return 0;for(unsigned k=0;k<5;k++)if(!isfinite(a[k])||!isfinite(b[k])||fabs(a[k])>100000000||fabs(b[k])>100000000)return 0;int start=a[2]<near;if(start==(b[2]<near))return 0;const double*target=start?a:b;double distance=fabs(b[2]-a[2]),travel=near-target[2];if(distance<=0||distance>=32767||travel<0||travel>=32767)return 0;int dl=(int)floor(distance),tl=(int)floor(travel);double fd=distance-dl,ft=travel-tl,result[5]={0};result[2]=near;
 for(unsigned k=0;k<5;k++){if(k==2)continue;double diff=b[k]-a[k];if(diff<INT32_MIN||diff>=INT32_MAX)return 0;int32_t base=(int32_t)floor(diff);double ff=diff-base,sum=0;for(unsigned i=0;i<2;i++)for(unsigned j=0;j<2;j++)for(unsigned q=0;q<2;q++){double w=(i?fd:1-fd)*(j?ft:1-ft)*(q?ff:1-ff);if(w==0)continue;uint32_t factor=(uint32_t)(tl+(int)j)*word(table,(size_t)(dl+(int)i)*4);int64_t product=(int64_t)(base+(int)q)*factor;sum+=w*bits((uint32_t)((uint64_t)product>>24));}result[k]=target[k]+(start?sum:-sum);if(!isfinite(result[k])||result[k]<INT32_MIN||result[k]>INT32_MAX||(k==0&&(result[k]< -32768||result[k]>32767)))return 0;}
 memcpy(out,result,sizeof(result));return 1;}
int nf_pc_road_project_near(const void*table,const double a[5],const double b[5],double near,double out[5]){double result[5];if(!out||!near_core(table,a,b,near,result))return 0;int visible=a[2]<near;const double*v=visible?b:a;double gap=v[2]-near;if(gap<1){double aa[5],bb[5],limit[5];memcpy(aa,a,sizeof(aa));memcpy(bb,b,sizeof(bb));(visible?bb:aa)[2]=near;if(!near_core(table,aa,bb,near,limit))return 0;double weight=1-gap;for(unsigned k=0;k<5;k++)if(k!=2)result[k]+=weight*(v[k]-limit[k]);}double distance=fabs(b[2]-a[2]);if(distance<1){double ratio=(near-a[2])/(b[2]-a[2]);for(unsigned k=0;k<5;k++)if(k!=2){double linear=a[k]+ratio*(b[k]-a[k]);result[k]=linear+distance*(result[k]-linear);}}memcpy(out,result,sizeof(result));return 1;}
static int source_project(const void*table,const double*p,unsigned shift,unsigned height,unsigned affine,const int32_t*projection,double out[5]){if(!nf_pc_road_project_point(table,p,p+3,shift,height,projection,out))return 0;if(affine)for(unsigned k=0;k<2;k++){int32_t base=(int32_t)floor(p[3+k]);double frac=p[3+k]-base,total=0;for(unsigned j=0;j<2;j++){double weight=j?frac:1-frac;if(weight==0)continue;int32_t a=base+(int)j,scaled=k?mul(a,bits(height)):shl(a,shift);total+=weight*shl(scaled,1);}out[3+k]=total;}return 1;}
int nf_pc_road_project_ring(const void*table,const double*world,unsigned count,const void*raw,size_t bytes,const void*camera,size_t camera_bytes,const int32_t projection[3],double out[64][5],unsigned*out_count){if(!table||!world||count<3||count>32||!raw||bytes!=288||!camera||!projection||!out||!out_count||word(raw,0)!=count||word(raw,12)>1)return 0;unsigned shift=word(raw,4),height=word(raw,8),affine=word(raw,12);double points[32][5],result[64][5];unsigned n=0;for(unsigned i=0;i<count;i++){if(!nf_pc_road_camera(camera,camera_bytes,world+i*3,points[i]))return 0;points[i][3]=get(raw,32+i*8);points[i][4]=get(raw,36+i*8);}
 for(unsigned i=0;i<count;i++){unsigned j=(i+1)%count;int a=points[i][2]<64,b=points[j][2]<64;if(a&&b)continue;if(a!=b){double v[5];if(!nf_pc_road_project_near(table,points[i],points[j],64,v)||!source_project(table,v,shift,height,affine,projection,result[n++]))return 0;}if(!b&&!source_project(table,points[j],shift,height,affine,projection,result[n++]))return 0;}memcpy(out,result,n*5*sizeof(double));*out_count=n;return 1;}

